export const shiftFaults={cableLow:'Tensión de cable insuficiente',cableHigh:'Tensión de cable excesiva',hTight:'Tope H demasiado cerrado',hOpen:'Tope H demasiado abierto',lTight:'Tope L demasiado cerrado',lOpen:'Tope L demasiado abierto'};
const setups={cableLow:[-.4,0,6],cableHigh:[.4,0,6],hTight:[0,.5,6],hOpen:[0,-.5,6],lTight:[0,0,5.5],lOpen:[0,0,6.5]};
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
export function createShift(mode='guided',random=Math.random){const ids=Object.keys(setups),fault=ids[Math.min(ids.length-1,Math.floor(random()*ids.length))],values=mode==='guided'?[-.4,.4,5.6]:setups[fault];return {id:crypto.randomUUID(),mode,causes:mode==='guided'?['cableLow','hTight','lTight']:[fault],trim:values[0],h:values[1],l:values[2],initial:[...values],requested:3,test:'gear',checks:{},hints:0,errors:0,events:[],done:false,feedback:'Selecciona marchas y observa dónde se pierde la alineación. Inspecciona los extremos por separado.',hintUsed:false};}
export function shiftState(s){const raw=s.test==='h'?-1:s.test==='l'?7:s.requested+s.trim,position=clamp(raw,s.h,s.l),target=s.test==='h'?0:s.test==='l'?6:s.requested,error=position-target,unsafe=position<-.15||position>6.15,aligned=Math.abs(error)<.15&&!unsafe;return {position,target,error,unsafe,aligned,engaged:clamp(Math.round(position),0,6),teeth:[12,14,16,19,23,28,32][clamp(Math.round(position),0,6)],status:unsafe?'Fuera del rango seguro: riesgo de salida de cadena':aligned?'Guía alineada con la corona objetivo':error<0?'Guía desplazada hacia las coronas pequeñas':'Guía desplazada hacia las coronas grandes'};}
export const shiftScore=s=>Math.max(0,100-10*s.hints-5*s.errors);
export function shiftAct(s,action,key,value){if(s.done)return false;
 if(action==='select'&&Number.isInteger(value)&&value>=0&&value<=6){s.requested=value;s.test='gear';const v=shiftState(s);s.checks['g'+value]=v.aligned;s.feedback=v.status;return true;}
 if(action==='test'&&['h','l'].includes(key)){s.test=key;const v=shiftState(s);s.checks[key]=v.aligned;s.feedback=(key==='h'?'Prueba H: se aísla la tensión del cable para examinar el extremo pequeño. ':'Prueba L: se examina el extremo grande. ')+v.status;return true;}
 if(action==='adjust'&&['trim','h','l'].includes(key)&&[-1,1].includes(value)){const old=Math.abs(s.trim)+Math.abs(s.h)+Math.abs(s.l-6),ranges={trim:[-.8,.8],h:[-.8,.8],l:[5.2,6.8]},next=Number(clamp(s[key]+value*.1,...ranges[key]).toFixed(2));if(next===s[key])return false;s[key]=next;const worse=Math.abs(s.trim)+Math.abs(s.h)+Math.abs(s.l-6)>old+.001;if(worse)s.errors++;s.checks={};s.events.push({key,delta:value*.1,worse});s.feedback=(s.mode==='guided'?(worse?'Este ajuste se aleja del objetivo. −5 puntos. ':'Ajuste en la dirección correcta. '):'Ajuste registrado. ')+ 'Vuelve a comprobar extremos y siete marchas; las pruebas anteriores se invalidan tras un ajuste.';return true;}
 if(action==='hint'){if(s.hintUsed)return false;s.hintUsed=true;s.hints++;s.feedback=Math.abs(s.h)>.14?'Aísla el cable y alinea el tope H con la corona pequeña. No uses el tensor para compensar un tope.':Math.abs(s.l-6)>.14?'Comprueba el extremo grande con la prueba L: debe alcanzarlo sin permitir salida hacia los radios.':'Si ambos extremos están bien pero fallan varias marchas intermedias, ajusta el tensor en pequeños pasos y recorre todo el cassette.';return true;}
 if(action==='verify'){const complete=['h','l',...Array.from({length:7},(_,i)=>'g'+i)].every(k=>s.checks[k]===true),calibrated=Math.abs(s.trim)<.15&&Math.abs(s.h)<.15&&Math.abs(s.l-6)<.15;s.done=complete&&calibrated;if(!s.done)s.errors++;s.feedback=s.done?'Transmisión verificada: siete marchas y ambos extremos correctos. En la bicicleta real confirma también alineación de patilla, longitud de cadena, ajuste B, fijaciones y prueba segura según el fabricante.':'Verificación incompleta o ajuste incorrecto. Repite las pruebas H, L y las siete marchas después del último ajuste. −5 puntos.';return true;}return false;
}
